// Вариант 3. Время условное: номер цикла × 3 секунды.
const T = 3;
const ranges = {s1:[0,60], s2:[0,100], s3:[0,1]};
const text = String(msg.payload ?? '').replace(/^\uFEFF/, '');
const lines = text.split(/\r?\n/);
const statements = [];
let count = 0;
const numberPattern = /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/;
for (let index = 0; index < lines.length; index++) {
    const line = lines[index].trim();
    if (!line) continue;
    const parts = line.split(/\s+/);
    const kind = parts.shift();
    if (kind !== 'DATA' && kind !== 'EVENT') continue;
    const f = {};
    for (const part of parts) {
        const eq = part.indexOf('=');
        if (eq > 0) f[part.slice(0,eq)] = part.slice(eq+1);
    }
    if (!/^\d+$/.test(f.n || '') || !Number.isSafeInteger(Number(f.n)) || Number(f.n) < 1 || Number(f.n) > 1000000000) {
        node.error('Некорректный номер n в строке ' + (index + 1) + '. База не изменена.', msg);
        return null;
    }
    const n = Number(f.n), time = n * T;
    if (kind === 'DATA') {
        count++;
        for (const sensor of ['s1','s2','s3']) {
            const raw = f[sensor];
            const value = raw !== undefined && numberPattern.test(raw) ? Number(raw) : NaN;
            if (Number.isFinite(value)) {
                statements.push(`INSERT INTO readings(n,t_s,sensor,value) VALUES(${n},${time},'${sensor}',${value});`);
            }
            if (!Number.isFinite(value) || value < ranges[sensor][0] || value > ranges[sensor][1] || (sensor === 's3' && value !== 0 && value !== 1)) {
                statements.push(`INSERT INTO events(n,t_s,type,message) VALUES(${n},${time},'FAULT','датчик ${sensor} вне диапазона');`);
            }
        }
    } else {
        if (!['THRESHOLD','NORMAL'].includes(f.type)) {
            node.error('Неизвестный тип EVENT в строке ' + (index + 1) + '. База не изменена.', msg);
            return null;
        }
        statements.push(`INSERT INTO events(n,t_s,type,message) VALUES(${n},${time},'${f.type}','');`);
    }
}
if (!count) {
    node.warn('В журнале нет строк DATA. Загрузка отменена: база не изменена.');
    return null;
}
const head = "BEGIN;\nDELETE FROM readings;\nDELETE FROM events;\nDELETE FROM sqlite_sequence WHERE name IN ('readings','events');\n";
msg.payload = head + statements.join('\n') + '\nCOMMIT;\n';
node.status({fill:'green',shape:'dot',text:'Строк DATA: ' + count});
return [null, msg];
